# Valida bodegas y cantidades, y calcula subtotales y total
flt = frappe.utils.flt
tipo = doc.tipo_movimiento

if tipo == "Entrada":
    doc.bodega_origen = None
    if not doc.bodega_destino:
        frappe.throw("Una Entrada necesita Bodega Destino.")

elif tipo == "Salida":
    doc.bodega_destino = None
    if not doc.bodega_origen:
        frappe.throw("Una Salida necesita Bodega Origen.")

elif tipo == "Transferencia":
    if not doc.bodega_origen or not doc.bodega_destino:
        frappe.throw("Una Transferencia necesita Bodega Origen y Bodega Destino.")
    if doc.bodega_origen == doc.bodega_destino:
        frappe.throw("La Bodega Origen y la Bodega Destino no pueden ser la misma.")

elif tipo == "Ajuste":
    doc.bodega_origen = None
    if not doc.bodega_destino:
        frappe.throw("Un Ajuste necesita Bodega Destino.")

if not doc.detalle:
    frappe.throw("Agrega al menos un producto en el detalle.")

total = 0
for row in doc.detalle:
    cantidad = flt(row.cantidad)
    if tipo == "Ajuste":
        if cantidad == 0:
            frappe.throw("Fila " + str(row.idx) + ": la cantidad del ajuste no puede ser 0.")
    elif cantidad <= 0:
        frappe.throw("Fila " + str(row.idx) + ": la cantidad debe ser mayor que 0.")

    row.subtotal = flt(cantidad * flt(row.costo_unitario), 2)
    total += row.subtotal

doc.total = total
